var app = new Vue({
  el: "#app",
  delimiters: ["[[", "]]"],
  data: {
    loading: [],
    replyText: [],
    coments: [],
  },
  props: {
    value: {
      type: Object,
      required: true,
    },
  },
  methods: {
    getData() {
      const path = window.location.origin + "/dashboard/live-comments/data";
      axios
        .get(path)
        .then((response) => {
          this.coments = response.data;
        })
        .catch((error) => {
          console.log(error);
        });
    },
    getShowID(ind, pos) {
      return ""+ind+pos
    },
    scrollToReply(ind, pos) {
      const reply = ""+ind+pos
      this.$refs[reply][0].scrollIntoView({ behavior: "smooth", block: "center" });
    },
    sendReply(reply, id, ind, pos) {
      const path = window.location.origin + "/dashboard/live-comments/" + id;
      axios
        .post(path, {
          data: reply,
        })
        .then((response) => {
          this.$set(this.coments[ind].comments[pos], "replyText", "");
          this.coments = response.data["data"];
          this.$notify({
            group: "notification",
            type: response.data["status"],
            title: response.data["title"],
            text: response.data["message"],
            duration: 2500,
            speed: 1000,
          });
        })
        .catch((error) => {
          console.log(error);
        });
    },
    refreshData() {
      this.loading.push("Loading");
      const path = window.location.origin + "/dashboard/live-comments";
      axios
        .post(path)
        .then((response) => {
          this.loading.splice(0, 1);
          this.coments = response.data;
        })
        .catch((error) => {
          console.log(error);
        });
    }
  },
  created() {
    this.getData();
  },
});
